static void InsertionSort(SElem* first, SElem* last, SLess comp)
{
    if (first == last) return;
    for (SElem* i = first + 1; i != last; ++i) {
        SElem v = *i; SElem* j = i;
        while (j != first && comp(v, *(j - 1))) { *j = *(j - 1); --j; }
        *j = v;
    }
