// Behaviour test for 0x0077E580 vector<CIntelligentPointer<CThing> >::reserve
#include <cstdio>
#include <cstdlib>
#include <new>

struct CThing { int id; };
struct CPtr {
    CThing* PItem;
    unsigned int pad;
    CPtr(CThing* t) : PItem(t), pad(0) { }
    CPtr(const CPtr& o) : PItem(o.PItem), pad(0) { }
